use serde_json::{json,Value};use sha2::{Digest,Sha256};use std::{fs,path::{Path,PathBuf},collections::BTreeMap};const R:&str="/home/ubuntu/src/zopro-perf-work/representative-groups175";const OLD:&str="/home/ubuntu/src/zopro-perf-work/deferred-groups175";
fn r(p:&str)->PathBuf{Path::new(R).join(p)}fn read(p:impl AsRef<Path>)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}fn hash(p:impl AsRef<Path>)->String{format!("{:x}",Sha256::digest(fs::read(p).unwrap()))}fn save(p:impl AsRef<Path>,v:&Value){fs::write(p,serde_json::to_vec_pretty(v).unwrap()).unwrap()}
fn main(){assert!(!r("plan.json").exists());let mut pins=BTreeMap::<String,String>::new();let old=read(Path::new(OLD).join("pins-before.json"));for(p,h)in old.as_object().unwrap(){assert_eq!(hash(p),h.as_str().unwrap());if !p.starts_with(OLD){pins.insert(p.clone(),h.as_str().unwrap().into());}}
for f in["builders.rs","index_map.rs","perf.rs","cases.json","analysis.rs","runner.rs","probe.rs"]{let p=Path::new(OLD).join(f);let s=fs::read_to_string(&p).unwrap().replace(OLD,R);fs::write(r(f),s).unwrap();pins.insert(p.display().to_string(),hash(p));}
let p=r("probe.rs");let s=fs::read_to_string(&p).unwrap();assert_eq!(s.matches("mod deferred;").count(),1);fs::write(&p,s.replace("mod deferred;","mod deferred;\nmod forecast;")).unwrap();
let cost=Path::new("/home/ubuntu/src/zk-tools/zopro/crates/zopro-core/src/msm_affine/grouping_cost.rs");let s=fs::read_to_string(cost).unwrap();let a=s.find("pub(super) fn add").unwrap();let b=s.find("pub(super) fn limits").unwrap();fs::write(r("forecast.rs"),format!("use core::mem::size_of;\n{}",&s[a..b])).unwrap();pins.insert(cost.display().to_string(),hash(cost));
let current=Path::new("/home/ubuntu/src/zk-tools/zopro/crates/zopro-core/src/msm_affine/grouping.rs");let s=fs::read_to_string(current).unwrap();let a=s.find("    let mut groups =\n").unwrap();let b=s.find("\n#[cfg(test)]\nmod tests;").unwrap();let original=s[a..b].replace("ScalarGroups {","Groups {").replace("            _reservation: reservation,\n","").replace("        _reservation: reservation,\n","").replace("ahash::RandomState::new()","state");assert_eq!(fs::read_to_string(r("builders.rs")).unwrap().matches(&original).count(),1);
save(r("extraction-audit.json"),&json!({"production_source_sha256":hash(current),"original_source_body_verbatim_after_adaptations":true,"original_adaptations":["constructor signature/result type","reservation omitted from component","caller supplies seeded state"],"swiss_reference_unchanged":true,"new_candidate":"one pass borrowed representative indices plus counts; successful-only scalar materialization; no tagged transition or second hash","forecast_functions_exact":true,"parent_two_pass_gate_remains_false":true,"production_changed":false}));
let mut plan=read(Path::new(OLD).join("plan.json"));plan["source_pins"]=json!(r("pins-before.json"));for step in plan["steps"].as_array_mut().unwrap(){for arg in step["argv"].as_array_mut().unwrap(){if let Some(s)=arg.as_str(){*arg=json!(s.replace(OLD,R));}}}for f in["prepare.rs","prepare","deferred.rs","forecast.rs","builders.rs","index_map.rs","probe.rs","perf.rs","cases.json","analysis.rs","runner.rs","design.md","extraction-audit.json"]{pins.insert(r(f).display().to_string(),hash(r(f)));}save(r("pins-before.json"),&json!(pins));save(r("plan.json"),&plan);println!("Prepared3nativecomponent steps/{}pins; original175+frozenlibraries verified;onepassrecords8B",pins.len());}
